import { Compozy } from "@compozy/client";

const compozy = await Compozy.connect();
console.log(`Connected to CompozyOS ${compozy.daemon.version}`);
const { workspace } = await compozy.workspaces.resolveWorkspace({
  body: { path: process.cwd() },
});
const { session } = await compozy.sessions.createSession({
  body: { workspace: workspace.id, agent_name: "claude" },
});
const reply = await compozy.prompt({
  workspaceId: workspace.id,
  sessionId: session.id,
  message: "List the three largest files in this repo.",
});
if (reply.kind === "stream") {
  for await (const chunk of reply.chunks) {
    if (chunk.type === "text-delta") process.stdout.write(chunk.delta);
  }
} else {
  console.log(reply.result.status, reply.result.queue_position);
}

run.go:
package main

import (
    "context"
    "errors"
    "fmt"
    "io"
    "log"
    "os"

    "github.com/compozy/compozy/sdk/go/client"
)

func main() {
    ctx := context.Background()
    c, err := client.New(ctx)
    if err != nil {
        log.Fatal(err)
    }
    cwd, err := os.Getwd()
    if err != nil {
        log.Fatal(err)
    }
    ws, err := c.ResolveWorkspace(ctx, client.ResolveWorkspaceRequest{Path: cwd})
    if err != nil {
        log.Fatal(err)
    }
    created, err := c.CreateSession(ctx, client.CreateSessionParams{}, client.CreateSessionRequest{
        Workspace: ws.Workspace.ID,
        AgentName: "claude",
    })
    if err != nil {
        log.Fatal(err)
    }
    stream, err := c.Prompt(ctx, client.PromptInput{
        WorkspaceID: ws.Workspace.ID,
        SessionID: created.Session.ID,
        Message: "List the three largest files in this repo.",
    })
    if err != nil {
        log.Fatal(err)
    }
    defer stream.Close()
    for {
        chunk, err := stream.Next()
        if errors.Is(err, io.EOF) {
            break
        }
        if err != nil {
            log.Fatal(err)
        }
        if chunk.Type == "text-delta" {
            fmt.Print(chunk.TextDelta())
        }
    }
}

